head.script:
scwin.callLog = [];
scwin.onpageload = function () {
	var tmpJSON = [
		{ "col1": "1", "col2": "원" },
		{ "col1": "2", "col2": "투" },
		{ "col1": "3", "col2": "쓰리" },
		{ "col1": "1", "col2": "포" },
		{ "col1": "1", "col2": "파이브" },
		{ "col1": "3", "col2": "식스" },
		{ "col1": "1", "col2": "세븐" },
		{ "col1": "2", "col2": "에이트" },
		{ "col1": "3", "col2": "나인" }
	];
	var tmpJSON2 = [
		{ "col1": "1", "col2": "A" },
		{ "col1": "2", "col2": "B" },
		{ "col1": "3", "col2": "C" },
		{ "col1": "1", "col2": "D" },
		{ "col1": "2", "col2": "E" },
		{ "col1": "3", "col2": "F" },
		{ "col1": "1", "col2": "G" },
		{ "col1": "2", "col2": "H" },
		{ "col1": "3", "col2": "I" }
	];
	dataList1.setJSON(tmpJSON);
	dataList2.setJSON(tmpJSON2);
	gridView1.setDrillDownDragDrop(true);
	gridView2.setDrillDownDragDrop(true);
};
// gridView2 의 dragStartFunction/dragEndFunction
scwin.dragStart = function (info) {
	scwin.callLog.push("dragStart " + info.parentRowIndex);
	return true; // true인 경우에만 drilldown dragDrop을 실행한다. -> dragEnd 함수로 인자를 넘긴다
};
scwin.dragEnd = function (toIndex, rowXml, info) {
	scwin.callLog.push("dragEnd " + toIndex + " " + info.fromRowIndex + " " + info.removedRowIndex);
	dataList1.removeRow(info.fromRowIndex);
	dataList2.insertJSON(toIndex, info.rowJSON);
};
// gridView1 의 dragStartFunction/dragEndFunction
scwin.dragStart2 = function (info) {
	scwin.callLog.push("dragStart2 " + info.parentRowIndex);
	return true;
};
scwin.dragEnd2 = function (toIndex, rowXml, info) {
	scwin.callLog.push("dragEnd2 " + toIndex + " " + info.fromRowIndex + " " + info.removedRowIndex);
	dataList2.removeRow(info.removedRowIndex);
	dataList1.setRowJSON(toIndex, info.rowJSON);
};
